window.AUTH=window.AUTH||{};window.AUTH["87-1279"]={"d":"87-1279","id":"1987/87-1279","n":"Morrison v. Olson","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting appellees","date":"","url":"https://www.justice.gov/osg/media/218191/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/alexia-morrison-independent-counsel-appellant-v-theodore-b-olson-et-al","toa":false,"n":76}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep487/usrep487654/usrep487654.pdf","tr":false,"items":[{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":8,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"op":6,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. San Jacinto Tin Co.","cite":"125 U.S. 273","y":1888,"id":"scdb/1887-183","sc":1,"sum":"A suit maybe brought by the United'States in any court of competent juris-. diction to set aside, cancel, or annul a patent for land issued in its name, on the ground that it was obtained by fraud or mistake.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"op":2,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"op":4,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Springer v. Philippine Islands","cite":"277 U.S. 189","y":1928,"id":"scdb/1927-161","sc":1,"sum":"1. Acts of the Philippine Legislature creating a coal company and a bank, the stock of which is largely owned by the Philippine government, provide that the power to vote the stock shall be vested in a \"Committee,\" in the one case, and in a \"Board of Control,\" in the other, each consisting of the Governor General, the President of the Senate, and the Speaker of the House of Representatives. Held, that the voting of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Ponzi v. Fessenden","cite":"258 U.S. 254","y":1922,"id":"scdb/1921-078","sc":1,"sum":"1. Our system of state and federal jurisdiction requires a spirit of reciprocal comity between courts to promote due and orderly procedure.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Thompson","cite":"251 U.S. 407","y":1920,"id":"scdb/1919-128","sc":1,"sum":"A judgment of the District Court sustaining a so-called motion to - quash, which in effect bars the United States from further prosecuting the alleged offense under the same or any other indictment, depriving the district attorney and the grand jury of their lawful powers over the subject, is subject to review by this court under the Criminal Appeals Act as a “judgment sustaining a special plea in bar.”","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Cox","cite":"342 F.2d 167","url":"https://www.courtlistener.com/c/F.2d/342/167/","by":{"0":""}},{"t":"case","label":"Ullman v. United States","cite":"350 U.S. 422","y":1956,"id":"1955/58","sc":1,"sum":"The Act is constitutional and the conviction is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Wayte v. United States","cite":"470 U.S. 598","y":1985,"id":"1984/83-1292","sc":1,"sum":"The Supreme Court held, 7-to-2, that the government's passive enforcement policy was constitutional.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Mendoza","cite":"464 U.S. 154","y":1984,"id":"1983/82-849","sc":1,"sum":"The United States may not be collaterally estopped on an issue such as the one involved here, adjudicated against it in an earlier lawsuit brought by a different party.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Chandler v. Judicial Council of the Tenth Circuit","cite":"398 U.S. 74","y":1970,"id":"1969/2_misc","sc":1,"sum":"On December 13, 1965, respondent, the Judicial Council of the Tenth Circuit, acting under 28 U, S. C. § 332, issued an order finding that petitioner was unable or unwilling to discharge his duties efficiently as a district judge for the Western District of Oklahoma (hereafter the district) and directing that he should not act in any case then or thereafter pending therein, that until the Council's further order no …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Nathan v. Smith","cite":"737 F.2d 1069","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/737/1069/","op":1,"by":{"0":""}},{"t":"case","label":"Muskrat v. United States","cite":"219 U.S. 346","y":1911,"id":"1900-1940/219us346","sc":1,"op":2,"sum":"The Court ruled that Congress could not create jurisdiction for judicial review of a specific matter by way of legislation.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Germaine","cite":"99 U.S. 508","y":1879,"id":"scdb/1878-198","sc":1,"op":4,"sum":"1. Civil surgeons appointed by the Commissioner of Pensions under sect. 4777 of the Revised Statutes are not officers of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Northern Pipeline Constr. Co. v. Marathon Pipe Line Co.","cite":"458 U.S. 50","id":"1981/81-150","sc":1,"op":1,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Eaton","cite":"169 U.S. 331","y":1898,"id":"scdb/1897-084","sc":1,"op":2,"sum":"Congress has power, under the Constitution, to vest in the President authority to appoint a subordinate officer, called a vice-consul, to be temporarily charged with the duty of performing the functions of the consular office.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Humphrey's Executor v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"op":23,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Wiener v. United States","cite":"357 U.S. 349","y":1958,"id":"1957/52","sc":1,"op":5,"sum":"The Court held that the President did not have the authority to remove individuals from the War Claims Commission at will.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Morgan v. TVA","cite":"115 F.2d 990","y":1940,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/115/990/","by":{"0":""}},{"t":"case","label":"Barry v. United States ex rel. Cunningham","cite":"279 U.S. 597","y":1929,"id":"scdb/1928-113","sc":1,"sum":"1. A resolution of the Senate which recites the refusal of a witness to answer questions asked of him by a committee pursuing an investigation under authority from the Senate, and which directs that he be attached and brought before the bar of the Senate \"to answer such questions pertinent to the matter under inquiry as the Senate through its said committee or the President of the Senate may propound,\" expresses the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"McGrain v. Daugherty","cite":"273 U.S. 135","y":1927,"id":"1900-1940/273us135","sc":1,"op":1,"sum":"The Court upheld Daugherty's contempt conviction, establishing a presumption that congressional investigations have a legislative purpose. This presumption was not overcome by showing that the committee also had another purpose, such as exposure of wrongdoing. This presumption would later restrict the Court's hand in clear cases of congressional overreaching while investigating communists after World War II.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Solomon","cite":"216 F. Supp. 835","y":1963,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./216/835/","op":1,"by":{"0":""}},{"t":"case","label":"Nixon v. Administrator of General Services","cite":"433 U.S. 425","y":1977,"id":"1976/75-1605","sc":1,"op":1,"sum":"The Court held that the act did not violate any of Nixon’s relevant constitutional rights. Justice Brennan first determined that the district court correctly limited the scope of its review to the constitutional consequences of the archival screenings because the Administrator had not yet promulgated any regulations.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Will","cite":"449 U.S. 200","y":1980,"id":"1980/79-983","sc":1,"op":1,"sum":"In two of the years in question, Congress effectively revoked automatic pay increases after the statutes guaranteeing those increases had already taken effect. This amounted to a reduction in salaries for judges and violated the Compensation Clause.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Atkins v. United States","cite":"556 F.2d 1028","y":1977,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/556/1028/","by":{"0":""}},{"t":"case","label":"United States v. Agnew","cite":"428 F. Supp. 1293","y":1977,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp./428/1293/","by":{"0":""}},{"t":"case","label":"Blair v. United States","cite":"250 U.S. 273","y":1919,"id":"scdb/1918-077","sc":1,"op":3,"sum":"It is the duty of this court to refrain from passing upon the constitutionality of an act of Congress when the interests of the party attacking it do not entitle bim to raise the question.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Gardner v. Toilet Goods Ass'n","cite":"387 U.S. 167","y":1967,"id":"1966/438","sc":1,"sum":"Under the standards set forth in Abbott Laboratories v. Gardner, ante, p. 136, namely, the appropriateness of the issues for judicial determination and the immediate severity of the regulations' impact on the respondents, the pre-enforcement challenge to these regulations is ripe for judicial review.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Abbott Labs v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"American Trucking Ass'ns, Inc. v. ICC","cite":"747 F.2d 787","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/747/787/","by":{"0":""}},{"t":"case","label":"United States v. Perkins","cite":"116 U.S. 483","y":1886,"id":"scdb/1885-120","sc":1,"op":4,"sum":"When Congress by law, vests the appointment of inferior officers in the heads of departments, it may limit and restrict the power of removal as it deems best for the public interests.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Sells Eng'g, Inc.","cite":"463 U.S. 418","y":1983,"id":"1982/81-1032","sc":1,"sum":"After respondents, a company having contracts with the Navy and company officials, were indicted by a federal grand jury for conspiracy to defraud the United States and tax fraud, the parties reached a plea bargain under which the individual respondents pleaded guilty to a count of conspiracy to defraud the Government by obstructing an Internal Revenue Service investigation, and other counts against respondents were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Brown v. United States","cite":"359 U.S. 41","y":1959,"id":"1958/4","sc":1,"op":1,"sum":"The Supreme Court held that the FMCA clearly provided Brown with immunity from prosecution based on his testimony. Because he could not possibly incriminate himself, he could not invoke the Fifth Amendment. There was no statutory cap on sentencing, so 15 months was not an abuse of discretion.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Gatto","cite":"763 F.2d 1040","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/763/1040/","by":{"0":""}},{"t":"case","label":"United States v. Chanen","cite":"549 F.2d 1306","url":"https://www.courtlistener.com/c/F.2d/549/1306/","by":{"0":""}},{"t":"case","label":"Hobson v. Hansen","cite":"265 F. Supp. 902","y":1967,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./265/902/","by":{"0":""}},{"t":"case","label":"National Petroleum Refiners Ass'n v. FTC","cite":"482 F.2d 672","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/482/672/","by":{"0":""}},{"t":"case","label":"Synar v. United States","cite":"626 F. Supp. 1374","url":"https://www.courtlistener.com/c/F.%20Supp./626/1374/","op":6,"by":{"0":""}},{"t":"case","label":"United States ex rel. Marcus v. Hess","cite":"317 U.S. 537","y":1943,"id":"scdb/1942-043","sc":1,"sum":"1. Section 5438 of the Revised Statutes, which subjects to the penalties therein prescribed \"Every person who.. causes to be presented, for payment... any claim upon or against the Government of the United States,... knowing such claim to be.. fraudulent...,\" held applicable to contractors who, by collusive bidding, obtained contracts with municipalities and school districts of a State for work on federal Public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Linda R.S. v. Richard D.","cite":"410 U.S. 614","y":1973,"id":"1972/71-6078","sc":1,"sum":"Although appellant has an interest in her child's support, application of Art. 602 would not result in support but only in the father's incarceration, and a private citizen lacks a judicially cognizable interest in the prosecution or nonprosecution of another. Pp. 616-619. 335 F. Supp. 804, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Allred","cite":"155 U.S. 591","y":1895,"id":"scdb/1894-064","sc":1,"sum":"A commissioner of a Circuit Court is an officer of the court, authorized by law, and is entitled to his fees in the following cases when certified by the court as correct:","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Go-Bart Importing Co. v. United States","cite":"282 U.S. 344","id":"scdb/1930-123","sc":1,"op":4,"sum":"(1) In the proceedings before him, the Commissionek acted merely as an officer of the District Court in a matter of which it had authority to take control at any time. P. 353. (2) Notwithstanding the order to show cause was addressed to the United States alone, the proceeding was in substance and effect against the United States Attorney and the prohibition agent in charge, the latter being required by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Rice v. Ames","cite":"180 U.S. 371","y":1901,"id":"scdb/1900-121","sc":1,"sum":"An appeal lies directly to this court from a judgment of the District Court in a habeas corpus case, where the constitutionality of a law of thp United States, or the validity or construction of a treaty is drawn in question.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Connelly v. United States","cite":"249 F.2d 576","y":1957,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/249/576/","by":{"0":""}},{"t":"case","label":"Miller v. United States","cite":"24 F.2d 353","url":"https://www.courtlistener.com/c/F.2d/24/353/","by":{"0":""}},{"t":"case","label":"Jones v. United States","cite":"179 F. 584","y":1910,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F./179/584/","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 49","url":"https://www.law.cornell.edu/uscode/text/28/49","stext":{"head":"§49. Assignment of judges to division to appoint independent counsels","paras":[[0,"(a) Beginning with the two-year period commencing on the date of the enactment of this section, three judges or justices shall be assigned for each successive two-year period to a division of the United States Court of Appeals for the District of Columbia to be the division of the court for the purpose of appointing independent counsels. The Clerk of the United States Court of Appeals for the District of Columbia Circuit shall serve as the clerk of such division of the court and shall provide such services as are needed by such division of the court."],[0,"(b) Except as provided under subsection (f) of this section, assignment to such division of the court shall not be a bar to other judicial assignments during the term of such division."],[0,"(c) In assigning judges or justices to sit on such division of the court, priority shall be given to senior circuit judges and retired justices."],[0,"(d) The Chief Justice of the United States shall designate and assign three circuit court judges or justices, one of whom shall be a judge of the United States Court of Appeals for the District of Columbia, to such division of the court. Not more than one judge or justice or senior or retired judge or justice may be named to such division from a particular court."],[0,"(e) Any vacancy in such division of the court shall be filled only for the remainder of the two-year period in which such vacancy occurs and in the same manner as initial assignments to such division were made."],[0,"(f) Except as otherwise provided in chapter 40 of this title, no member of such division of the court who participated in a function conferred on the division under chapter 40 of this title involving an independent counsel shall be eligible to participate in any judicial proceeding concerning a matter which involves such independent counsel while such independent counsel is serving in that office or which involves the exercise of such independent counsel's official duties, regardless of whether such independent counsel is still serving in that office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/49?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§49. Assignment of judges to division to appoint independent counsels","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 594","url":"https://www.law.cornell.edu/uscode/text/28/594","subs":["(a)"],"stext":{"head":"§594. Authority and duties of an independent counsel","paras":[[0,"(a) Authorities.—Notwithstanding any other provision of law, an independent counsel appointed under this chapter shall have, with respect to all matters in such independent counsel's prosecutorial jurisdiction established under this chapter, full power and independent authority to exercise all investigative and prosecutorial functions and powers of the Department of Justice, the Attorney General, and any other officer or employee of the Department of Justice, except that the Attorney General shall exercise direction or control as to those matters that specifically require the Attorney General's personal action under section 2516 of title 18. Such investigative and prosecutorial functions and powers shall include—"],[1,"(1) conducting proceedings before grand juries and other investigations;"],[1,"(2) participating in court proceedings and engaging in any litigation, including civil and criminal matters, that such independent counsel considers necessary;"],[1,"(3) appealing any decision of a court in any case or proceeding in which such independent counsel participates in an official capacity;"],[1,"(4) reviewing all documentary evidence available from any source;"],[1,"(5) determining whether to contest the assertion of any testimonial privilege;"],[1,"(6) receiving appropriate national security clearances and, if necessary, contesting in court (including, where appropriate, participating in in camera proceedings) any claim of privilege or attempt to withhold evidence on grounds of national security;"],[1,"(7) making applications to any Federal court for a grant of immunity to any witness, consistent with applicable statutory requirements, or for warrants, subpoenas, or other court orders, and, for purposes of sections 6003, 6004, and 6005 of title 18, exercising the authority vested in a United States attorney or the Attorney General;"],[1,"(8) inspecting, obtaining, or using the original or a copy of any tax return, in accordance with the applicable statutes and regulations, and, for purposes of section 6103 of the Internal Revenue Code of 1986 and the regulations issued thereunder, exercising the powers vested in a United States attorney or the Attorney General;"],[1,"(9) initiating and conducting prosecutions in any court of competent jurisdiction, framing and signing indictments, filing informations, and handling all aspects of any case, in the name of the United States; and"],[1,"(10) consulting with the United States attorney for the district in which any violation of law with respect to which the independent counsel is appointed was alleged to have occurred."],[0,"(b) Compensation.—"],[1,"(1) In general.—An independent counsel appointed under this chapter shall receive compensation at the per diem rate equal to the annual rate of basic pay payable for level IV of the Executive Schedule under section 5315 of title 5."],[1,"(2) Travel expenses.—Except as provided in paragraph (3), an independent counsel and persons appointed under subsection (c) shall be entitled to the payment of travel expenses as provided by subchapter I of chapter 57 of title 5, United States Code, including travel, per diem, and subsistence expenses in accordance with section 5703 of title 5."],[1,"(3) Travel to primary office.—"],[2,"(A) In general.—After 1 year of service under this chapter, an independent counsel and persons appointed under subsection (c) shall not be entitled to the payment of travel, per diem, or subsistence expenses under subchapter I of chapter 57 of title 5, United States Code, for the purpose of commuting to or from the city in which the primary office of the independent counsel or person is located. The 1-year period may be extended for successive 6-month periods if the independent counsel and the division of the court certify that the payment is in the public interest to carry out the purposes of this chapter."],[2,"(B) Relevant factors.—In making any certification under this paragraph with respect to travel and subsistence expenses of an independent counsel or person appointed under subsection (c), the independent counsel and the division of the court shall consider, among other relevant factors—"],[3,"(i) the cost to the Government of reimbursing such travel and subsistence expenses;"],[3,"(ii) the period of time for which the independent counsel anticipates that the activities of the independent counsel or person, as the case may be, will continue;"],[3,"(iii) the personal and financial burdens on the independent counsel or person, as the case may be, of relocating so that such travel and subsistence expenses would not be incurred; and"],[3,"(iv) the burdens associated with appointing a new independent counsel, or appointing another person under subsection (c), to replace the individual involved who is unable or unwilling to so relocate."],[0,"(c) Additional Personnel.—For the purposes of carrying out the duties of an office of independent counsel, such independent counsel may appoint, fix the compensation, and assign the duties of such employees as such independent counsel considers necessary (including investigators, attorneys, and part-time consultants). The positions of all such employees are exempted from the competitive service. Such employees shall be compensated at levels not to exceed those payable for comparable positions in the Office of United States Attorney for the District of Columbia under sections 548 and 550, but in no event shall any such employee be compensated at a rate greater than the rate of basic pay payable for level ES–4 of the Senior Executive Service Schedule under section 5382 of title 5, as adjusted for the District of Columbia under section 5304 of that title regardless of the locality in which an employee is employed."],[0,"(d) Assistance of Department of Justice.—"],[1,"(1) In carrying out functions.—An independent counsel may request assistance from the Department of Justice in carrying out the functions of the independent counsel, and the Department of Justice shall provide that assistance, which may include access to any records, files, or other materials relevant to matters within such independent counsel's prosecutorial jurisdiction, and the use of the resources and personnel necessary to perform such independent counsel's duties. At the request of an independent counsel, prosecutors, administrative personnel, and other employees of the Department of Justice may be detailed to the staff of the independent counsel."],[1,"(2) Payment of and reports on expenditures of independent counsel.—The Department of Justice shall pay all costs relating to the establishment and operation of any office of independent counsel. The Attorney General shall submit to the Congress, not later than 30 days after the end of each fiscal year, a report on amounts paid during that fiscal year for expenses of investigations and prosecutions by independent counsel. Each such report shall include a statement of all payments made for activities of independent counsel but may not reveal the identity or prosecutorial jurisdiction of any independent counsel which has not been disclosed under section 593(b)(4)."],[0,"(e) Referral of Other Matters to an Independent Counsel.—An independent counsel may ask the Attorney General or the division of the court to refer to the independent counsel matters related to the independent counsel's prosecutorial jurisdiction, and the Attorney General or the division of the court, as the case may be, may refer such matters. If the Attorney General refers a matter to an independent counsel on the Attorney General's own initiative, the independent counsel may accept such referral if the matter relates to the independent counsel's prosecutorial jurisdiction. If the Attorney General refers any matter to the independent counsel pursuant to the independent counsel's request, or if the independent counsel accepts a referral made by the Attorney General on the Attorney General's own initiative, the independent counsel shall so notify the division of the court."],[0,"(f) Compliance With Policies of the Department of Justice.—"],[1,"(1) In general.—An independent counsel shall, except to the extent that to do so would be inconsistent with the purposes of this chapter, comply with the written or other established policies of the Department of Justice respecting enforcement of the criminal laws. To determine these policies and policies under subsection (l)(1)(B), the independent counsel shall, except to the extent that doing so would be inconsistent with the purposes of this chapter, consult with the Department of Justice."],[1,"(2) National security.—An independent counsel shall comply with guidelines and procedures used by the Department in the handling and use of classified material."],[0,"(g) Dismissal of Matters.—The independent counsel shall have full authority to dismiss matters within the independent counsel's prosecutorial jurisdiction without conducting an investigation or at any subsequent time before prosecution, if to do so would be consistent with the written or other established policies of the Department of Justice with respect to the enforcement of criminal laws."],[0,"(h) Reports by Independent Counsel.—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/594?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§594. Authority and duties of an independent counsel","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 597","url":"https://www.law.cornell.edu/uscode/text/28/597","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 596","url":"https://www.law.cornell.edu/uscode/text/28/596","subs":["(a)(1)"],"stext":{"head":"§596. Removal of an independent counsel; termination of office","paras":[[0,"(a) Removal; Report on Removal.—"],[1,"(1) Grounds for removal.—An independent counsel appointed under this chapter may be removed from office, other than by impeachment and conviction, only by the personal action of the Attorney General and only for good cause, physical or mental disability (if not prohibited by law protecting persons from discrimination on the basis of such a disability),,1 or any other condition that substantially impairs the performance of such independent counsel's duties."],[1,"(2) Report to division of the court and congress.—If an independent counsel is removed from office, the Attorney General shall promptly submit to the division of the court and the Committees on the Judiciary of the Senate and the House of Representatives a report specifying the facts found and the ultimate grounds for such removal. The committees shall make available to the public such report, except that each committee may, if necessary to protect the rights of any individual named in the report or to prevent undue interference with any pending prosecution, postpone or refrain from publishing any or all of the report. The division of the court may release any or all of such report in accordance with section 594(h)(2)."],[1,"(3) Judicial review of removal.—An independent counsel removed from office may obtain judicial review of the removal in a civil action commenced in the United States District Court for the District of Columbia. A member of the division of the court may not hear or determine any such civil action or any appeal of a decision in any such civil action. The independent counsel may be reinstated or granted other appropriate relief by order of the court."],[0,"(b) Termination of Office.—"],[1,"(1) Termination by action of independent counsel.—An office of independent counsel shall terminate when—"],[2,"(A) the independent counsel notifies the Attorney General that the investigation of all matters within the prosecutorial jurisdiction of such independent counsel or accepted by such independent counsel under section 594(e), and any resulting prosecutions, have been completed or so substantially completed that it would be appropriate for the Department of Justice to complete such investigations and prosecutions; and"],[2,"(B) the independent counsel files a final report in compliance with section 594(h)(1)(B)."],[1,"(2) Termination by division of the court.—The division of the court, either on its own motion or upon the request of the Attorney General, may terminate an office of independent counsel at any time, on the ground that the investigation of all matters within the prosecutorial jurisdiction of such independent counsel or accepted by such independent counsel under section 594(e), and any resulting prosecutions, have been completed or so substantially completed that it would be appropriate for the Department of Justice to complete such investigations and prosecutions. At the time of such termination, the independent counsel shall file the final report required by section 594(h)(1)(B). If the Attorney General has not made a request under this paragraph, the division of the court shall determine on its own motion whether termination is appropriate under this paragraph no later than 2 years after the appointment of an independent counsel, at the end of the succeeding 2-year period, and thereafter at the end of each succeeding 1-year period."],[0,"(c) Audits.—(1) On or before June 30 of each year, an independent counsel shall prepare a statement of expenditures for the 6 months that ended on the immediately preceding March 31. On or before December 31 of each year, an independent counsel shall prepare a statement of expenditures for the fiscal year that ended on the immediately preceding September 30. An independent counsel whose office is terminated prior to the end of the fiscal year shall prepare a statement of expenditures on or before the date that is 90 days after the date on which the office is terminated."],[0,"(2) The Comptroller General shall—"],[1,"(A) conduct a financial review of a mid-year statement and a financial audit of a year-end statement and statement on termination; and"],[1,"(B) report the results to the Committee on the Judiciary, Committee on Governmental Affairs, and Committee on Appropriations of the Senate and the Committee on the Judiciary, Committee on Government Operations, and Committee on Appropriations of the House of Representatives not later than 90 days following the submission of each such statement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/596?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§596. Removal of an independent counsel; termination of office","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 593","url":"https://www.law.cornell.edu/uscode/text/28/593","subs":["(b)"],"stext":{"head":"§593. Duties of the division of the court","paras":[[0,"(a) Reference to Division of the Court.—The division of the court to which this chapter refers is the division established under section 49 of this title."],[0,"(b) Appointment and Jurisdiction of Independent Counsel.—"],[1,"(1) Authority.—Upon receipt of an application under section 592(c), the division of the court shall appoint an appropriate independent counsel and shall define that independent counsel's prosecutorial jurisdiction."],[1,"(2) Qualifications of independent counsel.—The division of the court shall appoint as independent counsel an individual who has appropriate experience and who will conduct the investigation and any prosecution in a prompt, responsible, and cost-effective manner. The division of the court shall seek to appoint as independent counsel an individual who will serve to the extent necessary to complete the investigation and any prosecution without undue delay. The division of the court may not appoint as an independent counsel any person who holds any office of profit or trust under the United States."],[1,"(3) Scope of prosecutorial jurisdiction.—In defining the independent counsel's prosecutorial jurisdiction, the division of the court shall assure that the independent counsel has adequate authority to fully investigate and prosecute the subject matter with respect to which the Attorney General has requested the appointment of the independent counsel, and all matters related to that subject matter. Such jurisdiction shall also include the authority to investigate and prosecute Federal crimes, other than those classified as Class B or C misdemeanors or infractions, that may arise out of the investigation or prosecution of the matter with respect to which the Attorney General's request was made, including perjury, obstruction of justice, destruction of evidence, and intimidation of witnesses."],[1,"(4) Disclosure of identity and prosecutorial jurisdiction.—An independent counsel's identity and prosecutorial jurisdiction (including any expansion under subsection (c)) may not be made public except upon the request of the Attorney General or upon a determination of the division of the court that disclosure of the identity and prosecutorial jurisdiction of such independent counsel would be in the best interests of justice. In any event, the identity and prosecutorial jurisdiction of such independent counsel shall be made public when any indictment is returned, or any criminal information is filed, pursuant to the independent counsel's investigation."],[0,"(c) Expansion of Jurisdiction.—"],[1,"(1) In general.—The division of the court, upon the request of the Attorney General, may expand the prosecutorial jurisdiction of an independent counsel, and such expansion may be in lieu of the appointment of another independent counsel."],[1,"(2) Procedure for request by independent counsel.—(A) If the independent counsel discovers or receives information about possible violations of criminal law by persons as provided in section 591, which are not covered by the prosecutorial jurisdiction of the independent counsel, the independent counsel may submit such information to the Attorney General. The Attorney General shall then conduct a preliminary investigation of the information in accordance with the provisions of section 592, except that such preliminary investigation shall not exceed 30 days from the date such information is received. In making the determinations required by section 592, the Attorney General shall give great weight to any recommendations of the independent counsel."],[1,"(B) If the Attorney General determines, after according great weight to the recommendations of the independent counsel, that there are no reasonable grounds to believe that further investigation is warranted, the Attorney General shall promptly so notify the division of the court and the division of the court shall have no power to expand the jurisdiction of the independent counsel or to appoint another independent counsel with respect to the matters involved."],[1,"(C) If—"],[2,"(i) the Attorney General determines that there are reasonable grounds to believe that further investigation is warranted; or"],[2,"(ii) the 30-day period referred to in subparagraph (A) elapses without a notification to the division of the court that no further investigation is warranted,"],[1,"the division of the court shall expand the jurisdiction of the appropriate independent counsel to include the matters involved or shall appoint another independent counsel to investigate such matters."],[0,"(d) Return for Further Explanation.—Upon receipt of a notification under section 592 or subsection (c)(2)(B) of this section from the Attorney General that there are no reasonable grounds to believe that further investigation is warranted with respect to information received under this chapter, the division of the court shall have no authority to overrule this determination but may return the matter to the Attorney General for further explanation of the reasons for such determination."],[0,"(e) Vacancies.—If a vacancy in office arises by reason of the resignation, death, or removal of an independent counsel, the division of the court shall appoint an independent counsel to complete the work of the independent counsel whose resignation, death, or removal caused the vacancy, except that in the case of a vacancy arising by reason of the removal of an independent counsel, the division of the court may appoint an acting independent counsel to serve until any judicial review of such removal is completed."],[0,"(f) Attorneys' Fees.—"],[1,"(1) Award of fees.—Upon the request of an individual who is the subject of an investigation conducted by an independent counsel pursuant to this chapter, the division of the court may, if no indictment is brought against such individual pursuant to that investigation, award reimbursement for those reasonable attorneys' fees incurred by that individual during that investigation which would not have been incurred but for the requirements of this chapter. The division of the court shall notify the the 1 independent counsel who conducted the investigation and Attorney 2 General of any request for attorneys' fees under this subsection."],[1,"(2) Evaluation of fees.—The division of the court shall direct such independent counsel and the Attorney General to file a written evaluation of any request for attorneys' fees under this subsection, addressing—"],[2,"(A) the sufficiency of the documentation;"],[2,"(B) the need or justification for the underlying item;"],[2,"(C) whether the underlying item would have been incurred but for the requirements of this chapter; and"],[2,"(D) the reasonableness of the amount of money requested."],[0,"(g) Disclosure of Information.—The division of the court may, subject to section 594(h)(2), allow the disclosure of any notification, application, or any other document, material, or memorandum supplied to the division of the court under this chapter."],[0,"(h) Amicus Curiae Briefs.—When presented with significant legal issues, the division of the court may disclose sufficient information about the issues to permit the filing of timely amicus curiae briefs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/593?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§593. Duties of the division of the court","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 595","url":"https://www.law.cornell.edu/uscode/text/28/595","subs":["(b)(2)"],"stext":{"head":"§595. Congressional oversight","paras":[[0,"(a) Oversight of Conduct of Independent Counsel.—"],[1,"(1) Congressional oversight.—The appropriate committees of the Congress shall have oversight jurisdiction with respect to the official conduct of any independent counsel appointed under this chapter, and such independent counsel shall have the duty to cooperate with the exercise of such oversight jurisdiction."],[1,"(2) Reports to congress.—An independent counsel appointed under this chapter shall submit to the Congress annually a report on the activities of the independent counsel, including a description of the progress of any investigation or prosecution conducted by the independent counsel. Such report may omit any matter that in the judgment of the independent counsel should be kept confidential, but shall provide information adequate to justify the expenditures that the office of the independent counsel has made."],[0,"(b) Oversight of Conduct of Attorney General.—Within 15 days after receiving an inquiry about a particular case under this chapter, which is a matter of public knowledge, from a committee of the Congress with jurisdiction over this chapter, the Attorney General shall provide the following information to that committee with respect to that case:"],[1,"(1) When the information about the case was received."],[1,"(2) Whether a preliminary investigation is being conducted, and if so, the date it began."],[1,"(3) Whether an application for the appointment of an independent counsel or a notification that further investigation is not warranted has been filed with the division of the court, and if so, the date of such filing."],[0,"(c) Information Relating to Impeachment.—An independent counsel shall advise the House of Representatives of any substantial and credible information which such independent counsel receives, in carrying out the independent counsel's responsibilities under this chapter, that may constitute grounds for an impeachment. Nothing in this chapter or section 49 of this title shall prevent the Congress or either House thereof from obtaining information in the course of an impeachment proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/595?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§595. Congressional oversight","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 592","url":"https://www.law.cornell.edu/uscode/text/28/592","subs":["(c)(1)"],"stext":{"head":"§592. Preliminary investigation and application for appointment of an independent counsel","paras":[[0,"(a) Conduct of Preliminary Investigation.—"],[1,"(1) In general.—A preliminary investigation conducted under this chapter shall be of such matters as the Attorney General considers appropriate in order to make a determination, under subsection (b) or (c), on whether further investigation is warranted, with respect to each potential violation, or allegation of a violation, of criminal law. The Attorney General shall make such determination not later than 90 days after the preliminary investigation is commenced, except that, in the case of a preliminary investigation commenced after a congressional request under subsection (g), the Attorney General shall make such determination not later than 90 days after the request is received. The Attorney General shall promptly notify the division of the court specified in section 593(a) of the commencement of such preliminary investigation and the date of such commencement."],[1,"(2) Limited authority of attorney general.—(A) In conducting preliminary investigations under this chapter, the Attorney General shall have no authority to convene grand juries, plea bargain, grant immunity, or issue subpoenas."],[1,"(B)(i) The Attorney General shall not base a determination under this chapter that information with respect to a violation of criminal law by a person is not specific and from a credible source upon a determination that such person lacked the state of mind required for the violation of criminal law."],[1,"(ii) The Attorney General shall not base a determination under this chapter that there are no reasonable grounds to believe that further investigation is warranted, upon a determination that such person lacked the state of mind required for the violation of criminal law involved, unless there is clear and convincing evidence that the person lacked such state of mind."],[1,"(3) Extension of time for preliminary investigation.—The Attorney General may apply to the division of the court for a single extension, for a period of not more than 60 days, of the 90-day period referred to in paragraph (1). The division of the court may, upon a showing of good cause, grant such extension."],[0,"(b) Determination That Further Investigation Not Warranted.—"],[1,"(1) Notification of division of the court.—If the Attorney General, upon completion of a preliminary investigation under this chapter, determines that there are no reasonable grounds to believe that further investigation is warranted, the Attorney General shall promptly so notify the division of the court, and the division of the court shall have no power to appoint an independent counsel with respect to the matters involved."],[1,"(2) Form of notification.—Such notification shall contain a summary of the information received and a summary of the results of the preliminary investigation."],[0,"(c) Determination That Further Investigation is Warranted.—"],[1,"(1) Application for appointment of independent counsel.—The Attorney General shall apply to the division of the court for the appointment of an independent counsel if—"],[2,"(A) the Attorney General, upon completion of a preliminary investigation under this chapter, determines that there are reasonable grounds to believe that further investigation is warranted; or"],[2,"(B) the 90-day period referred to in subsection (a)(1), and any extension granted under subsection (a)(3), have elapsed and the Attorney General has not filed a notification with the division of the court under subsection (b)(1)."],[1,"In determining under this chapter whether reasonable grounds exist to warrant further investigation, the Attorney General shall comply with the written or other established policies of the Department of Justice with respect to the conduct of criminal investigations."],[1,"(2) Receipt of additional information.—If, after submitting a notification under subsection (b)(1), the Attorney General receives additional information sufficient to constitute grounds to investigate the matters to which such notification related, the Attorney General shall—"],[2,"(A) conduct such additional preliminary investigation as the Attorney General considers appropriate for a period of not more than 90 days after the date on which such additional information is received; and"],[2,"(B) otherwise comply with the provisions of this section with respect to such additional preliminary investigation to the same extent as any other preliminary investigation under this section."],[0,"(d) Contents of Application.—Any application for the appointment of an independent counsel under this chapter shall contain sufficient information to assist the division of the court in selecting an independent counsel and in defining that independent counsel's prosecutorial jurisdiction so that the independent counsel has adequate authority to fully investigate and prosecute the subject matter and all matters related to that subject matter."],[0,"(e) Disclosure of Information.—Except as otherwise provided in this chapter or as is deemed necessary for law enforcement purposes, no officer or employee of the Department of Justice or an office of independent counsel may, without leave of the division of the court, disclose to any individual outside the Department of Justice or such office any notification, application, or any other document, materials, or memorandum supplied to the division of the court under this chapter. Nothing in this chapter shall be construed as authorizing the withholding of information from the Congress."],[0,"(f) Limitation on Judicial Review.—The Attorney General's determination under this chapter to apply to the division of the court for the appointment of an independent counsel shall not be reviewable in any court."],[0,"(g) Congressional Request.—"],[1,"(1) By judiciary committee or members thereof.—The Committee on the Judiciary of either House of the Congress, or a majority of majority party members or a majority of all nonmajority party members of either such committee, may request in writing that the Attorney General apply for the appointment of an independent counsel."],[1,"(2) Report by attorney general pursuant to request.—Not later than 30 days after the receipt of a request under paragraph (1), the Attorney General shall submit, to the committee making the request, or to the committee on which the persons making the request serve, a report on whether the Attorney General has begun or will begin a preliminary investigation under this chapter of the matters with respect to which the request is made, in accordance with subsection (a) or (c) of section 591, as the case may be. The report shall set forth the reasons for the Attorney General's decision regarding such preliminary investigation as it relates to each of the matters with respect to which the congressional request is made. If there is such a preliminary investigation, the report shall include the date on which the preliminary investigation began or will begin."],[1,"(3) Submission of information in response to congressional request.—At the same time as any notification, application, or any other document, material, or memorandum is supplied to the division of the court pursuant to this section with respect to a preliminary investigation of any matter with respect to which a request is made under paragraph (1), such notification, application, or other document, material, or memorandum shall be supplied to the committee making the request, or to the committee on which the persons making the request serve. If no application for the appointment of an independent counsel is made to the division of the court under this section pursuant to such a preliminary investigation, the Attorney General shall submit a report to that committee stating the reasons why such application was not made, addressing each matter with respect to which the congressional request was made."],[1,"(4) Disclosure of information.—Any report, notification, application, or other document, material, or memorandum supplied to a committee under this subsection shall not be revealed to any third party, except that the committee may, either on its own initiative or upon the request of the Attorney General, make public such portion or portions of such report, notification, application, document, material, or memorandum as will not in the committee's judgment prejudice the rights of any individual."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/592?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§592. Preliminary investigation and application for appointment of an independent counsel","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 671","url":"https://www.law.cornell.edu/uscode/text/28/671","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 631","url":"https://www.law.cornell.edu/uscode/text/28/631","subs":["(a)"],"stext":{"head":"§631. Appointment and tenure","paras":[[0,"(a) The judges of each United States district court and the district courts of the Virgin Islands, Guam, and the Northern Mariana Islands shall appoint United States magistrate judges in such numbers and to serve at such locations within the judicial districts as the Judicial Conference may determine under this chapter. In the case of a magistrate judge appointed by the district court of the Virgin Islands, Guam, or the Northern Mariana Islands, this chapter shall apply as though the court appointing such a magistrate judge were a United States district court. Where there is more than one judge of a district court, the appointment, whether an original appointment or a reappointment, shall be by the concurrence of a majority of all the judges of such district court, and when there is no such concurrence, then by the chief judge. Where the conference deems it desirable, a magistrate judge may be designated to serve in one or more districts adjoining the district for which he is appointed. Such a designation shall be made by the concurrence of a majority of the judges of each of the district courts involved and shall specify the duties to be performed by the magistrate judge in the adjoining district or districts."],[0,"(b) No individual may be appointed or reappointed to serve as a magistrate judge under this chapter unless:"],[0,"(1) He has been for at least five years a member in good standing of the bar of the highest court of a State, the District of Columbia, the Commonwealth of Puerto Rico, the Territory of Guam, the Commonwealth of the Northern Mariana Islands, or the Virgin Islands of the United States, except that an individual who does not meet the bar membership requirements of this paragraph may be appointed and serve as a part-time magistrate judge if the appointing court or courts and the conference find that no qualified individual who is a member of the bar is available to serve at a specific location;"],[0,"(2) He is determined by the appointing district court or courts to be competent to perform the duties of the office;"],[0,"(3) In the case of an individual appointed to serve in a national park, he resides within the exterior boundaries of that park, or at some place reasonably adjacent thereto;"],[0,"(4) He is not related by blood or marriage to a judge of the appointing court or courts at the time of his initial appointment; and"],[0,"(5) He is selected pursuant to standards and procedures promulgated by the Judicial Conference of the United States. Such standards and procedures shall contain provision for public notice of all vacancies in magistrate judge positions and for the establishment by the district courts of merit selection panels, composed of residents of the individual judicial districts, to assist the courts in identifying and recommending persons who are best qualified to fill such positions."],[0,"(c) A magistrate judge may hold no other civil or military office or employment under the United States: Provided, however, That, with the approval of the conference, a part-time referee in bankruptcy or a clerk or deputy clerk of a court of the United States may be appointed and serve as a part-time United States magistrate judge, but the conference shall fix the aggregate amount of compensation to be received for performing the duties of part-time magistrate judge and part-time referee in bankruptcy, clerk or deputy clerk: And provided further, That retired officers and retired enlisted personnel of the Regular and Reserve components of the Army, Navy, Air Force, Marine Corps, and Coast Guard, members of the Reserve components of the Army, Navy, Air Force, Marine Corps, and Coast Guard 1 members of the Space Force, and members of the Army National Guard of the United States, the Air National Guard of the United States, and the Naval Militia and of the National Guard of a State, territory, or the District of Columbia, except the National Guard disbursing officers who are on a full-time salary basis, may be appointed and serve as United States magistrate judges."],[0,"(d) Except as otherwise provided in sections 375 and 636(h) of this title, no individual may serve under this chapter after having attained the age of seventy years: Provided, however, That upon a majority vote of all the judges of the appointing court or courts, which is taken upon the magistrate judge's attaining age seventy and upon each subsequent anniversary thereof, a magistrate judge who has attained the age of seventy years may continue to serve and may be reappointed under this chapter."],[0,"(e) The appointment of any individual as a full-time magistrate judge shall be for a term of eight years, and the appointment of any individuals as a part-time magistrate judge shall be for a term of four years, except that the term of a full-time or part-time magistrate judge appointed under subsection (k) 2 shall expire upon—"],[1,"(1) the expiration of the absent magistrate judge's term,"],[1,"(2) the reinstatement of the absent magistrate judge in regular service in office as a magistrate judge,"],[1,"(3) the failure of the absent magistrate judge to make timely application under subsection (j) 2 of this section for reinstatement in regular service in office as a magistrate judge after discharge or release from military service,"],[1,"(4) the death or resignation of the absent magistrate judge, or"],[1,"(5) the removal from office of the absent magistrate judge pursuant to subsection (i) of this section,"],[0,"whichever may first occur."],[0,"(f) Upon the expiration of his term, a magistrate judge may, by a majority vote of the judges of the appointing district court or courts and with the approval of the judicial council of the circuit, continue to perform the duties of his office until his successor is appointed, or for 180 days after the date of the expiration of the magistrate judge's term, whichever is earlier."],[0,"(g) Each individual appointed as a magistrate judge under this section shall take the oath or affirmation prescribed by section 453 of this title before performing the duties of his office."],[0,"(h) Each appointment made by a judge or judges of a district court shall be entered of record in such court, and notice of such appointment shall be given at once by the clerk of that court to the Director."],[0,"(i) Removal of a magistrate judge during the term for which he is appointed shall be only for incompetency, misconduct, neglect of duty, or physical or mental disability, but a magistrate judge's office shall be terminated if the conference determines that the services performed by his office are no longer needed. Removal shall be by the judges of the district court for the judicial district in which the magistrate judge serves; where there is more than one judge of a district court, removal shall not occur unless a majority of all the judges of such court concur in the order of removal; and when there is a tie vote of the judges of the district court on the question of the removal or retention in office of a magistrate judge, then removal shall be only by a concurrence of a majority of all the judges of the council. In the case of a magistrate judge appointed under the third sentence of subsection (a) of this section, removal shall not occur unless a majority of all the judges of the appointing district courts concur in the order of removal; and where there is a tie vote on the question of the removal or retention in office of a magistrate judge, then removal shall be only by a concurrence of a majority of all the judges of the council or councils. Before any order or removal shall be entered, a full specification of the charges shall be furnished to the magistrate judge, and he shall be accorded by the judge or judges of the removing court, courts, council, or councils an opportunity to be heard on the charges."],[0,"(j) Upon the grant by the appropriate district court or courts of a leave of absence to a magistrate judge entitled to such relief under chapter 43 of title 38, such court or courts may proceed to appoint, in the manner specified in subsection (a) of this section, another magistrate judge, qualified for appointment and service under subsections (b), (c), and (d) of this section, who shall serve for the period specified in subsection (e) of this section."],[0,"(k) A United States magistrate judge appointed under this chapter shall be exempt from the provisions of subchapter I of chapter 63 of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/631?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§631. Appointment and tenure","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(b)"],"by":{"0":""}},{"t":"usc","label":"18 U.S.C. § 287","url":"https://www.law.cornell.edu/uscode/text/18/287","by":{"0":""}},{"t":"usc","label":"25 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/25/201","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 546","url":"https://www.law.cornell.edu/uscode/text/28/546","by":{"0":""}},{"t":"usc","label":"18 U.S.C. § 208","url":"https://www.law.cornell.edu/uscode/text/18/208","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 528","url":"https://www.law.cornell.edu/uscode/text/28/528","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 56","url":"https://www.law.cornell.edu/uscode/text/15/56","subs":["(b)"],"by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","subs":["(b)"],"by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 2076","url":"https://www.law.cornell.edu/uscode/text/15/2076","subs":["(b)(7)(B)"],"by":{"0":""}},{"t":"usc","label":"47 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/47/401","subs":["(c)"],"by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 547","url":"https://www.law.cornell.edu/uscode/text/28/547","by":{"0":""}},{"t":"usc","label":"2 U.S.C. § 437d","url":"https://www.law.cornell.edu/uscode/text/2/437d","subs":["(a)(6)"],"by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 7171","url":"https://www.law.cornell.edu/uscode/text/42/7171","subs":["(i)"],"by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 2053","url":"https://www.law.cornell.edu/uscode/text/15/2053","subs":["(a)"],"stext":{"head":"§2053. Consumer Product Safety Commission","paras":[[0,"(a) Establishment; Chairman"],[0,"An independent regulatory commission is hereby established, to be known as the Consumer Product Safety Commission, consisting of five Commissioners who shall be appointed by the President, by and with the advice and consent of the Senate. In making such appointments, the President shall consider individuals who, by reason of their background and expertise in areas related to consumer products and protection of the public from risks to safety, are qualified to serve as members of the Commission. The Chairman shall be appointed by the President, by and with the advice and consent of the Senate, from among the members of the Commission. An individual may be appointed as a member of the Commission and as Chairman at the same time. Any member of the Commission may be removed by the President for neglect of duty or malfeasance in office but for no other cause."],[0,"(b) Term; vacancies"],[0,"(1) Except as provided in paragraph (2), (A) the Commissioners first appointed under this section shall be appointed for terms ending three, four, five, six, and seven years, respectively, after October 27, 1972, the term of each to be designated by the President at the time of nomination; and (B) each of their successors shall be appointed for a term of seven years from the date of the expiration of the term for which his predecessor was appointed."],[0,"(2) Any Commissioner appointed to fill a vacancy occurring prior to the expiration of the term for which his predecessor was appointed shall be appointed only for the remainder of such term. A Commissioner may continue to serve after the expiration of this term until his successor has taken office, except that he may not so continue to serve more than one year after the date on which his term would otherwise expire under this subsection."],[0,"(c) Restrictions on Commissioner's outside activities"],[0,"Not more than three of the Commissioners shall be affiliated with the same political party. No individual (1) in the employ of, or holding any official relation to, any person engaged in selling or manufacturing consumer products, or (2) owning stock or bonds of substantial value in a person so engaged, or (3) who is in any other manner pecuniarily interested in such a person, or in a substantial supplier of such a person, shall hold the office of Commissioner. A Commissioner may not engage in any other business, vocation, or employment."],[0,"(d) Quorum; seal; Vice Chairman"],[0,"No vacancy in the Commission shall impair the right of the remaining Commissioners to exercise all the powers of the Commission, but three members of the Commission shall constitute a quorum for the transaction of business, except that if there are only three members serving on the Commission because of vacancies in the Commission, two members of the Commission shall constitute a quorum for the transaction of business, and if there are only two members serving on the Commission because of vacancies in the Commission, two members shall constitute a quorum for the six month period beginning on the date of the vacancy which caused the number of Commission members to decline to two. The Commission shall have an official seal of which judicial notice shall be taken. The Commission shall annually elect a Vice Chairman to act in the absence or disability of the Chairman or in case of a vacancy in the office of the Chairman."],[0,"(e) Offices"],[0,"The Commission shall maintain a principal office and such field offices as it deems necessary and may meet and exercise any of its powers at any other place."],[0,"(f) Functions of Chairman; request for appropriations"],[0,"(1) The Chairman of the Commission shall be the principal executive officer of the Commission, and he shall exercise all of the executive and administrative functions of the Commission, including functions of the Commission with respect to (A) the appointment and supervision of personnel employed under the Commission (other than personnel employed regularly and full time in the immediate offices of commissioners other than the Chairman), (B) the distribution of business among personnel appointed and supervised by the Chairman and among administrative units of the Commission, and (C) the use and expenditure of funds."],[0,"(2) In carrying out any of his functions under the provisions of this subsection the Chairman shall be governed by general policies of the Commission and by such regulatory decisions, findings, and determinations as the Commission may by law be authorized to make."],[0,"(3) Requests or estimates for regular, supplemental, or deficiency appropriations on behalf of the Commission may not be submitted by the Chairman without the prior approval of the Commission."],[0,"(g) Executive Director; officers and employees"],[0,"(1)(A) The Chairman, subject to the approval of the Commission, shall appoint as officers of the Commission an Executive Director, a General Counsel, an Associate Executive Director for Engineering Sciences, an Associate Executive Director for Epidemiology, an Associate Executive Director for Compliance and Administrative Litigation, an Associate Executive Director for Health Sciences, an Associate Executive Director for Economic Analysis, an Associate Executive Director for Administration, an Associate Executive Director for Field Operations, a Director for Office of Program, Management, and Budget, and a Director for Office of Information and Public Affairs. Any other individual appointed to a position designated as an Associate Executive Director shall be appointed by the Chairman, subject to the approval of the Commission. The Chairman may only appoint an attorney to the position of Associate Executive Director of Compliance and Administrative Litigation except the position of acting Associate Executive Director of Compliance and Administrative Litigation."],[0,"(B)(i) No individual may be appointed to such a position on an acting basis for a period longer than 90 days unless such appointment is approved by the Commission."],[0,"(ii) The Chairman, with the approval of the Commission, may remove any individual serving in a position appointed under subparagraph (A)."],[0,"(C) Subparagraph (A) shall not be construed to prohibit appropriate reorganizations or changes in classification."],[0,"(2) The Chairman, subject to subsection (f)(2), may employ such other officers and employees (including attorneys) as are necessary in the execution of the Commission's functions."],[0,"(3) In addition to the number of positions authorized by section 5108(a) of title 5, the Chairman, subject to the approval of the Commission, and subject to the standards and procedures prescribed by chapter 51 of title 5, may place a total of twelve positions in grades GS–16, GS–17, and GS–18."],[0,"(4) The appointment of any officer (other than a Commissioner) or employee of the Commission shall not be subject, directly or indirectly, to review or approval by any officer or entity within the Executive Office of the President."],[0,"(5) The Chairman may provide to officers and employees of the Commission who are appointed or assigned by the Commission to serve abroad (as defined in section 102 of the Foreign Service Act of 1980 (22 U.S.C. 3902)) travel benefits similar to those authorized for members of the Foreign Service of the United Service under chapter 9 1 of such Act (22 U.S.C. 4081 et seq.)."],[0,"(h) Omitted"],[0,"(i) Civil action against United States"],[0,"Subsections (a) and (h) of section 2680 of title 28 do not prohibit the bringing of a civil action on a claim against the United States which—"],[1,"(1) is based upon—"],[2,"(A) misrepresentation or deceit on the part of the Commission or any employee thereof, or"],[2,"(B) any exercise or performance, or failure to exercise or perform, a discretionary function on the part of the Commission or any employee thereof, which exercise, performance, or failure was grossly negligent; and"],[1,"(2) is not made with respect to any agency action (as defined in section 551(13) of title 5)."],[0,"In the case of a civil action on a claim based upon the exercise or performance of, or failure to exercise or perform, a discretionary function, no judgment may be entered against the United States unless the court in which such action was brought determines (based upon consideration of all the relevant circumstances, including the statutory responsibility of the Commission and the public interest in encouraging rather than inhibiting the exercise of discretion) that such exercise, performance, or failure to exercise or perform was unreasonable."],[0,"(j) Agenda and priorities; establishment and comments"],[0,"At least 30 days before the beginning of each fiscal year, the Commission shall establish an agenda for Commission action under the Acts under its jurisdiction and, to the extent feasible, shall establish priorities for such actions. Before establishing such agenda and priorities, the Commission shall conduct a public hearing on the agenda and priorities and shall provide reasonable opportunity for the submission of comments."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/2053?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2053. Consumer Product Safety Commission","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"47 U.S.C. § 154","url":"https://www.law.cornell.edu/uscode/text/47/154","subs":["(c)"],"by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 242","url":"https://www.law.cornell.edu/uscode/text/12/242","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","stext":{"head":"§41. Federal Trade Commission established; membership; vacancies; seal","paras":[[0,"A commission is created and established, to be known as the Federal Trade Commission (hereinafter referred to as the Commission), which shall be composed of five Commissioners, who shall be appointed by the President, by and with the advice and consent of the Senate. Not more than three of the Commissioners shall be members of the same political party. The first Commissioners appointed shall continue in office for terms of three, four, five, six, and seven years, respectively, from September 26, 1914, the term of each to be designated by the President, but their successors shall be appointed for terms of seven years, except that any person chosen to fill a vacancy shall be appointed only for the unexpired term of the Commissioner whom he shall succeed: Provided, however, That upon the expiration of his term of office a Commissioner shall continue to serve until his successor shall have been appointed and shall have qualified..1 The President shall choose a chairman from the Commission's membership. No Commissioner shall engage in any other business, vocation, or employment. Any Commissioner may be removed by the President for inefficiency, neglect of duty, or malfeasance in office. A vacancy in the Commission shall not impair the right of the remaining Commissioners to exercise all the powers of the Commission."],[0,"The Commission shall have an official seal, which shall be judicially noticed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/41?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§41. Federal Trade Commission established; membership; vacancies; seal","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 78d","url":"https://www.law.cornell.edu/uscode/text/15/78d","subs":["(a)"],"by":{"0":""}}]};